// Development-only public FileStream/BinaryReader API. No Pascal compiler.
using System;using System.IO;using System.Text;
class BinaryStreamReference{
 static uint seed=0x7316ac4;static uint Next(){unchecked{seed=seed*1664525+1013904223;return seed;}}
 static string Hex(byte[] bytes,int count){return count==0?"-":BitConverter.ToString(bytes,0,count).Replace("-","").ToLowerInvariant();}
 static void Main(string[] args){string folder=Path.Combine(Path.GetTempPath(),"ABC binary stream "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string path=Path.Combine(folder,"二进制-данные.bin");int rows=0;try{using(var log=new StreamWriter(args[0],false,new UTF8Encoding(false))){log.WriteLine("# scenario\toperation\targument\tinput_hex\toutcome\tposition\tlength");for(int scenario=0;scenario<16;++scenario){FileStream file=null;BinaryReader reader=null;bool closed=false;for(int step=0;step<270;++step){string op="",input="-",outcome="ok";long argument=0;byte[] bytes=null;
 if(step==0)op="create";else if(step==1)op="write";else if(step==2)op="conflict";else if(step==3)op="conflict-create";else if(step==4)op="seek";else if(step==5)op="i32";else if(step==262)op="close";else if(step==263)op="read";else if(step==264)op="write";else if(step==265)op="close";else if(step==266)op="open";else if(step==267)op="read";else if(step==268)op="close";else if(step==269)op="snapshot";else {op=new[]{"seek","write","read","i32","truncate","negative","big","empty"}[Next()%8];if(file.Position>4096&&op!="seek"&&op!="big"&&op!="negative")op="seek";}
 if(op=="seek")argument=step==4?0:Next()%97;if(op=="negative")argument=(Next()&1)==0?-1:long.MinValue;if(op=="big")argument=0x100000003L+(Next()%65536);if(op=="read")argument=step==263?1:step==267?4096:Next()%18;if(op=="write"||op=="empty"){bytes=new byte[op=="empty"?0:step==1?17:(int)(Next()%18)];for(int n=0;n<bytes.Length;++n)bytes[n]=(byte)Next();input=Hex(bytes,bytes.Length);}
 try{switch(op){case "create":case "open":file=new FileStream(path,op=="create"?FileMode.Create:FileMode.Open);reader=new BinaryReader(file,Encoding.UTF8,true);closed=false;break;case "conflict":case "conflict-create":using(var other=new FileStream(path,op=="conflict"?FileMode.Open:FileMode.Create)){}break;case "write":case "empty":file.Write(bytes,0,bytes.Length);break;case "read":var data=new byte[(int)argument];int count=file.Read(data,0,data.Length);outcome=Hex(data,count);break;case "i32":outcome=reader.ReadInt32().ToString(System.Globalization.CultureInfo.InvariantCulture);break;case "seek":case "negative":case "big":file.Position=argument;break;case "truncate":file.SetLength(file.Position);break;case "close":file.Close();closed=true;break;case "snapshot":var all=File.ReadAllBytes(path);outcome=Hex(all,all.Length);break;}}
 catch(Exception e){outcome=e.GetType().Name;}
 log.WriteLine(scenario+"\t"+op+"\t"+argument+"\t"+input+"\t"+outcome+"\t"+(closed?"-":file.Position.ToString())+"\t"+(closed?"-":file.Length.ToString()));++rows;
 }if(reader!=null)reader.Dispose();if(file!=null)file.Dispose();}}}finally{Directory.Delete(folder,true);}Console.WriteLine(rows+" actual binary stream traces");}
}